
(() => {
'use strict';
const APP_VERSION='1.1.1-clean';
const STORAGE_KEY='ourspace_household_organizer_v1';
const BACKEND=Object.freeze({
  webApp:'https://script.google.com/macros/s/AKfycbw_wdbMMTKFNXjisAyGEdn5LwJaYQOH8FgrfbkSMItNCqyQYWD2uxcYX57L2Cap_ALn3w/exec',
  library:'https://script.google.com/macros/library/d/1OAfZ4nWbCcdTCS87wHag_mWLAfrGcUu_UJx_GzMQWu6hiuRfcFXHogVp/1',
  libraryVersion:'1'
});
const DAY=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const MONTH=['January','February','March','April','May','June','July','August','September','October','November','December'];
const TYPE_META={task:{label:'Task',icon:'✅'},care:{label:'Care',icon:'🌿'},dbt_adhd:{label:'DBT / ADHD',icon:'🧠'}};
const FREQ_LABEL={on_demand:'On demand',daily:'Daily',weekly:'Weekly',monthly:'Monthly',annually:'Annually'};
const DEFAULT_REWARD={on_demand:5,daily:10,weekly:25,monthly:50,annually:100};
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const uid=(prefix='id')=>`${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`;
const pad=n=>String(n).padStart(2,'0');
const ymd=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const parseDate=s=>{const [y,m,d]=String(s||'').split('-').map(Number);return new Date(y||1970,(m||1)-1,d||1)};
const today=()=>ymd(new Date());
const niceDate=(s,opts={weekday:'short',month:'short',day:'numeric'})=>parseDate(s).toLocaleDateString(undefined,opts);
const nowIso=()=>new Date().toISOString();
const clamp=(n,min,max)=>Math.min(max,Math.max(min,n));
const asArray=v=>Array.isArray(v)?v:[];
const stripHtml=s=>{const d=document.createElement('div');d.innerHTML=s||'';return d.textContent||''};
function sanitizeHTML(html=''){
  const doc=new DOMParser().parseFromString(`<div>${html}</div>`,'text/html');
  const allowed=new Set(['DIV','P','BR','B','STRONG','I','EM','U','S','STRIKE','UL','OL','LI','H1','H2','H3','BLOCKQUOTE','CODE','PRE','A','SPAN']);
  [...doc.body.querySelectorAll('*')].forEach(el=>{
    if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);return;}
    [...el.attributes].forEach(a=>{if(!(el.tagName==='A'&&a.name==='href'))el.removeAttribute(a.name)});
    if(el.tagName==='A'){const h=el.getAttribute('href')||'';if(!/^https?:|^mailto:|^tel:/i.test(h))el.removeAttribute('href');else{el.target='_blank';el.rel='noopener';}}
  });
  return doc.body.firstElementChild?.innerHTML||'';
}
function splitCurrency(totalCopper){let total=Math.max(0,Math.floor(Number(totalCopper)||0));const original=total;const platinum=Math.floor(total/1000);total%=1000;const gold=Math.floor(total/100);total%=100;const silver=Math.floor(total/10);const copper=total%10;return{platinum,gold,silver,copper,totalCopper:original};}
function formatCurrency(totalCopper,compact=false){const c=splitCurrency(totalCopper);const parts=[];if(c.platinum)parts.push(`${c.platinum}${compact?'p':' platinum'}`);if(c.gold)parts.push(`${c.gold}${compact?'g':' gold'}`);if(c.silver)parts.push(`${c.silver}${compact?'s':' silver'}`);if(c.copper||!parts.length)parts.push(`${c.copper}${compact?'c':' copper'}`);return parts.join(compact?' · ':', ');}
function currencyCoins(total){const c=splitCurrency(total);return `<div class="coin-row"><span class="coin"><i class="coin-dot platinum"></i>${c.platinum} platinum</span><span class="coin"><i class="coin-dot gold"></i>${c.gold} gold</span><span class="coin"><i class="coin-dot silver"></i>${c.silver} silver</span><span class="coin"><i class="coin-dot copper"></i>${c.copper} copper</span></div>`;}
const LEGACY_PLACEHOLDER_TASKS=new Set(['Do the dishes','Take medication / vitamins','Use one grounding or DBT skill','Weekly home reset','Monthly household check-in','Test smoke and CO alarms']);
const LEGACY_PLACEHOLDER_LISTS=new Set(['Groceries','Household supplies']);
const LEGACY_PLACEHOLDER_REWARDS=new Set(['Choose tonight’s movie','Favorite snack or drink','Special outing fund']);
function defaultState(){
  const m1={id:'william',name:'William',nickname:'Dino',emoji:'🦖',color:'#336699',role:'Member',walletCopper:0};
  const m2={id:'jasper',name:'Jasper',nickname:'Squishy',emoji:'⭐',color:'#336699',role:'Member',walletCopper:0};
  return {
    version:APP_VERSION,
    household:{name:'OurSpace Household',members:[m1,m2]},currentMemberId:m1.id,
    tasks:[],completions:[],events:[],notes:[],lists:[],photos:[],rewards:[],ledger:[],dayStarts:{},activity:[],
    settings:{theme:'system',textScale:1,startWeek:0,notifications:false,sound:false,backendSync:true,calendarTaskTypes:['task','care','dbt_adhd'],placeholderCleanupVersion:1},
    ui:{route:'today',calendarMonth:today().slice(0,7),selectedDate:today(),taskFilter:'all',taskFrequency:'all',taskAssignee:'all',settingsTab:'household',search:''}
  };
}
function migrate(raw){
  const base=defaultState();if(!raw||typeof raw!=='object')return base;
  const merged={...base,...raw,household:{...base.household,...raw.household},settings:{...base.settings,...raw.settings},ui:{...base.ui,...raw.ui}};
  merged.household.members=asArray(merged.household.members).map((m,i)=>({...base.household.members[i]||{id:uid('member'),name:'Member',emoji:'🙂',color:'#336699',role:'Member',walletCopper:0},...m,walletCopper:Math.max(0,Math.floor(Number(m.walletCopper)||0))}));
  if(!merged.household.members.length)merged.household.members=base.household.members;
  merged.currentMemberId=merged.household.members.some(m=>m.id===merged.currentMemberId)?merged.currentMemberId:merged.household.members[0].id;
  ['tasks','completions','events','notes','lists','photos','rewards','ledger','activity'].forEach(k=>merged[k]=asArray(merged[k]));
  if(Number(raw.settings?.placeholderCleanupVersion||0)<1){
    const removedTaskIds=new Set(merged.tasks.filter(t=>LEGACY_PLACEHOLDER_TASKS.has(String(t.title||''))).map(t=>t.id));
    merged.tasks=merged.tasks.filter(t=>!removedTaskIds.has(t.id));
    merged.completions=merged.completions.filter(c=>!removedTaskIds.has(c.taskId));
    merged.photos=merged.photos.map(p=>removedTaskIds.has(p.taskId)?{...p,taskId:''}:p);
    merged.lists=merged.lists.filter(l=>!LEGACY_PLACEHOLDER_LISTS.has(String(l.title||'')));
    merged.rewards=merged.rewards.filter(r=>!LEGACY_PLACEHOLDER_REWARDS.has(String(r.title||'')));
    merged.settings.placeholderCleanupVersion=1;
  }
  merged.version=APP_VERSION;
  return merged;
}
let state=(()=>{try{return migrate(JSON.parse(localStorage.getItem(STORAGE_KEY)))}catch{return defaultState()}})();
const ACTIVE_HOUSEHOLD_ID=document.documentElement.dataset.profile==='jasper'?'jasper':'william';
state.currentMemberId=ACTIVE_HOUSEHOLD_ID;
let modalCleanup=null;
function save(renderTop=true){state.currentMemberId=ACTIVE_HOUSEHOLD_ID;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));applySettings();if(renderTop)renderChrome();}
function ingestProfessorTasks(){
  const bridge=window.OurSpaceModuleBridge;if(!bridge)return;
  const profile=ACTIVE_HOUSEHOLD_ID;let changed=false;
  for(const p of bridge.list(profile)){
    if(state.tasks.some(t=>t.onyxPairId===p.pairId&&t.assignee===profile))continue;
    const id='onyx-dbt-'+profile+'-'+p.pairId;
    state.tasks.push({id,title:'Professor Onyx: '+p.title,description:'Assigned DBT practice. The handout and editable worksheet are linked below.',type:'dbt_adhd',frequency:'on_demand',active:true,priority:'medium',assignee:profile,time:'',rewardCopper:5,weekdays:[],tags:['onyx','dbt','professor'],createdAt:p.createdAt||nowIso(),updatedAt:nowIso(),onyxPairId:p.pairId,onyxLinks:{handout:p.handoutUrl,worksheet:p.worksheetUrl}});
    changed=true;
  }
  if(changed){save(false);render();}
}
window.addEventListener('storage',e=>{if(e.key?.startsWith('ourspace.onyx.professor.tasks.v1.'))ingestProfessorTasks();});
window.addEventListener('focus',()=>ingestProfessorTasks());
window.addEventListener('ourspace:onyx-task-saved',ingestProfessorTasks);
setTimeout(ingestProfessorTasks,0);
setTimeout(()=>{void window.OurSpaceModuleBridge?.syncFromBackend?.({force:true});},3300);

function member(id=state.currentMemberId){return state.household.members.find(m=>m.id===id)||state.household.members[0];}
function logActivity(text,kind='info'){state.activity.unshift({id:uid('activity'),text,kind,at:nowIso(),memberId:state.currentMemberId});state.activity=state.activity.slice(0,250);}
function toast(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;document.getElementById('toastStack').appendChild(el);setTimeout(()=>el.remove(),3600);}
function isDue(task,dateStr){if(!task.active)return false;const d=parseDate(dateStr);if(task.frequency==='daily')return true;if(task.frequency==='weekly'){const days=asArray(task.weekdays);return(days.length?days:[new Date(task.createdAt||Date.now()).getDay()]).includes(d.getDay())}if(task.frequency==='monthly')return d.getDate()===Number(task.dayOfMonth||1);if(task.frequency==='annually')return d.getMonth()+1===Number(task.month||1)&&d.getDate()===Number(task.dayOfMonth||1);return false;}
function completionsFor(taskId,dateStr){return state.completions.filter(c=>c.taskId===taskId&&c.date===dateStr&&!c.undoneAt)}
function isCompleted(task,dateStr){return task.frequency==='on_demand'?completionsFor(task.id,dateStr).length>0:completionsFor(task.id,dateStr).length>0}
function tasksForDate(dateStr,{includeOnDemand=false,type=null}={}){return state.tasks.filter(t=>(!type||t.type===type)&&((includeOnDemand&&t.frequency==='on_demand')||isDue(t,dateStr))).sort(taskSort)}
function taskSort(a,b){const ac=isCompleted(a,state.ui.selectedDate||today()),bc=isCompleted(b,state.ui.selectedDate||today());if(ac!==bc)return ac?1:-1;const p={high:0,medium:1,low:2};return(p[a.priority]??1)-(p[b.priority]??1)||(a.time||'99:99').localeCompare(b.time||'99:99')||a.title.localeCompare(b.title)}
function memberOptions(selected='shared'){return `<option value="shared" ${selected==='shared'?'selected':''}>Shared / anyone</option>`+state.household.members.map(m=>`<option value="${esc(m.id)}" ${selected===m.id?'selected':''}>${esc(m.emoji)} ${esc(m.name)}</option>`).join('')}
function taskTypeBadge(t){return `<span class="badge ${t.type}">${TYPE_META[t.type]?.icon||'✅'} ${TYPE_META[t.type]?.label||'Task'}</span>`}
function recurrenceText(t){if(t.frequency==='weekly'&&t.weekdays?.length)return `${t.weekdays.map(d=>DAY[d]).join(', ')}${t.time?' at '+t.time:''}`;if(t.frequency==='monthly')return `Day ${t.dayOfMonth}${t.time?' at '+t.time:''}`;if(t.frequency==='annually')return `${MONTH[(t.month||1)-1]} ${t.dayOfMonth}${t.time?' at '+t.time:''}`;return `${FREQ_LABEL[t.frequency]||t.frequency}${t.time?' at '+t.time:''}`}
function currentWallet(){return member().walletCopper||0}
function renderChrome(){
  state.currentMemberId=ACTIVE_HOUSEHOLD_ID;
  document.getElementById('osHouseholdModule').dataset.theme='lightning';
  document.getElementById('osHouseholdModule').style.setProperty('--text-scale',String(state.settings.textScale||1));
  document.getElementById('todayLabel').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
  document.getElementById('walletTop').textContent=`🪙 ${formatCurrency(currentWallet(),true)}`;
  document.querySelectorAll('.nav [data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===state.ui.route));
}
function applySettings(){renderChrome()}
function route(name){state.ui.route=name;state.ui.search=document.getElementById('householdGlobalSearch')?.value||state.ui.search||'';save(false);render();document.getElementById('householdSidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function taskRow(t,dateStr=today(),compact=false){const comps=completionsFor(t.id,dateStr);const done=t.frequency!=='on_demand'&&comps.length;const assigned=t.assignee==='shared'?'Anyone':member(t.assignee)?.name||'Anyone';return `<article class="task-row ${done?'completed':''}" data-task-id="${esc(t.id)}">
  <button class="task-check ${done?'done':''}" data-action="toggle-task" data-id="${esc(t.id)}" data-date="${dateStr}" aria-label="${done?'Undo':'Complete'} ${esc(t.title)}">${done?'✓':''}</button>
  <div><div class="task-title">${esc(t.title)}</div><div class="task-meta">${taskTypeBadge(t)}<span class="badge">${esc(recurrenceText(t))}</span><span class="badge">👤 ${esc(assigned)}</span><span class="badge priority-${esc(t.priority||'medium')}">${esc(t.priority||'medium')}</span>${comps.length?`<span class="badge done">${comps.length} logged today</span>`:''}</div>${t.description?`<div class="task-desc">${esc(t.description)}</div>`:''}${t.onyxLinks?`<div class="task-meta onyx-task-resources"><a href="${esc(t.onyxLinks.handout)}" target="_blank" rel="noopener noreferrer">Read handout</a> <a href="${esc(t.onyxLinks.worksheet)}" target="_blank" rel="noopener noreferrer">Open worksheet</a></div>`:''}${t.tags?.length?`<div class="task-meta">${t.tags.map(x=>`<span>#${esc(x)}</span>`).join(' ')}</div>`:''}</div>
  <div class="task-actions"><span class="reward">+${formatCurrency(t.rewardCopper||1,true)}</span><button class="btn small" data-action="photo-task" data-id="${esc(t.id)}">📷</button>${t.frequency==='on_demand'&&comps.length?`<button class="btn small primary" data-action="toggle-task" data-id="${esc(t.id)}" data-date="${dateStr}">Log again</button>`:''}${!compact?`<button class="btn small" data-action="edit-task" data-id="${esc(t.id)}">Edit</button>`:''}</div>
</article>`}
function renderToday(){
  const d=today(),due=tasksForDate(d,{includeOnDemand:false}),ondemand=state.tasks.filter(t=>t.frequency==='on_demand');const done=due.filter(t=>isCompleted(t,d)).length;const pct=due.length?Math.round(done/due.length*100):0;const started=state.dayStarts[d];
  const events=eventsForDate(d);const pinned=state.notes.filter(n=>n.pinned).slice(0,3);const recentActivity=state.activity.slice(0,6);
  const hasContent=state.tasks.length||state.events.length||state.notes.length||state.lists.length||state.photos.length||state.rewards.length||state.activity.length||state.ledger.length||state.household.members.some(m=>(m.walletCopper||0)>0);
  if(!hasContent)return `${pageHead(`Hello, ${esc(member().name)}`,niceDate(d,{weekday:'long',month:'long',day:'numeric'}),`<button class="btn primary" data-open="task">＋ Task</button>`)}
    <section class="card"><div class="card-head"><h2>Household organizer</h2></div><p class="muted">Add entries manually or import JSON.</p><div class="actions"><button class="btn primary" data-open="task">Add task</button><button class="btn" data-open="event">Add event</button><button class="btn" data-open="note">New note</button><button class="btn" data-action="import-open">Import JSON</button></div></section>`;
  return `${pageHead(`Hello, ${esc(member().name)}`,`Here is ${niceDate(d,{weekday:'long',month:'long',day:'numeric'})}. Nothing is lost if a day is missed.`,`<button class="btn primary" data-action="start-day">${started?'Day started ✓':'Start day'}</button><button class="btn" data-open="task">＋ Task</button>`)}
  <section class="card hero"><div><h2>${started?'Your day is open':'Start gently, then choose one thing'}</h2><p class="muted">Today has <strong>${due.length-done}</strong> scheduled item${due.length-done===1?'':'s'} remaining. Progress photos are available, but proof is never required.</p><div class="progress"><i style="width:${pct}%"></i></div><p class="tiny muted">${done} of ${due.length} scheduled items complete · ${pct}%</p><div class="actions"><button class="btn accent" data-action="quick-focus">Choose my next task</button><button class="btn" data-route="calendar">Open calendar</button></div></div><div class="hero-art" aria-hidden="true">🏡</div></section>
  <section class="grid cols-4" style="margin-top:16px">
    <div class="card stat"><div class="stat-icon">✅</div><div><strong>${done}</strong><span>completed today</span></div></div>
    <div class="card stat"><div class="stat-icon">📋</div><div><strong>${Math.max(0,due.length-done)}</strong><span>scheduled remaining</span></div></div>
    <div class="card stat"><div class="stat-icon">🪙</div><div><strong>${formatCurrency(currentWallet(),true)}</strong><span>${esc(member().name)}’s wallet</span></div></div>
    <div class="card stat"><div class="stat-icon">📷</div><div><strong>${state.photos.filter(p=>p.date===d).length}</strong><span>progress photos today</span></div></div>
  </section>
  <section class="grid cols-2" style="margin-top:16px">
    <div class="card"><div class="card-head"><h2>Today’s tasks</h2><button class="btn small" data-route="tasks">All tasks</button></div><div class="task-list">${due.length?due.map(t=>taskRow(t,d,true)).join(''):`<div class="empty">No scheduled tasks today. Add one or use an on-demand item.</div>`}</div></div>
    <div class="grid"><div class="card"><div class="card-head"><h2>Calendar</h2><button class="btn small" data-open="event">＋ Event</button></div><div class="agenda">${events.length?events.slice(0,6).map(eventAgenda).join(''):`<div class="empty">No events today.</div>`}</div></div>
    <div class="card"><div class="card-head"><h2>Quick capture</h2><button class="btn small" data-route="notes">Notes</button></div><div class="quick-capture"><input class="input" id="quickNoteInput" placeholder="Write a thought, reminder, or household note…"><button class="btn primary" data-action="quick-note">Save</button></div></div></div>
  </section>
  <section class="grid cols-2" style="margin-top:16px">
    <div class="card"><div class="card-head"><h2>On-demand care & skills</h2><button class="btn small" data-route="dbt">Open DBT / ADHD</button></div><div class="task-list">${ondemand.length?ondemand.slice(0,5).map(t=>taskRow(t,d,true)).join(''):`<div class="empty">No on-demand items yet.</div>`}</div></div>
    <div class="card"><div class="card-head"><h2>Pinned notes</h2><button class="btn small" data-open="note">＋ Note</button></div>${pinned.length?`<div class="note-grid">${pinned.map(noteCard).join('')}</div>`:`<div class="empty">Pin notes to keep household information here.</div>`}</div>
  </section>
  <section class="card" style="margin-top:16px"><div class="card-head"><h2>Recent household activity</h2><span class="tiny muted">Local activity log</span></div>${recentActivity.length?`<div class="ledger">${recentActivity.map(a=>`<div class="ledger-row"><div>${esc(a.text)}<div class="tiny muted">${new Date(a.at).toLocaleString()}</div></div><span>${esc(member(a.memberId)?.emoji||'🏠')}</span></div>`).join('')}</div>`:`<div class="empty">Completions, photos, notes, and redemptions will appear here.</div>`}</section>`;
}
function renderTasks(type=null){
  const title=type==='care'?'Care':type==='dbt_adhd'?'DBT / ADHD':'Tasks';const sub=type==='care'?'Personal, pet, and household care routines.':type==='dbt_adhd'?'On-demand and recurring supports without streak pressure.':'Household chores, projects, and recurring responsibilities.';
  let tasks=state.tasks.filter(t=>!type||t.type===type);const q=(state.ui.search||'').toLowerCase();if(q)tasks=tasks.filter(t=>`${t.title} ${t.description} ${(t.tags||[]).join(' ')}`.toLowerCase().includes(q));if(state.ui.taskFrequency!=='all')tasks=tasks.filter(t=>t.frequency===state.ui.taskFrequency);if(state.ui.taskAssignee!=='all')tasks=tasks.filter(t=>t.assignee===state.ui.taskAssignee);
  const groups={scheduled:tasks.filter(t=>t.frequency!=='on_demand'&&!isCompleted(t,today())),onDemand:tasks.filter(t=>t.frequency==='on_demand'),completed:tasks.filter(t=>t.frequency!=='on_demand'&&isCompleted(t,today()))};
  const header=pageHead(title,sub,`<button class="btn primary" data-open="task" data-type="${type||'task'}">＋ Add ${type==='care'?'care item':type==='dbt_adhd'?'support':'task'}</button><button class="btn" data-action="import-open">Import JSON</button>`);
  if(!tasks.length)return `${header}<div class="card empty">No entries yet.</div>`;
  return `${header}
  <div class="card flat" style="margin-bottom:14px"><div class="chips">${['all','on_demand','daily','weekly','monthly','annually'].map(f=>`<button class="chip ${state.ui.taskFrequency===f?'active':''}" data-action="task-freq" data-value="${f}">${f==='all'?'All schedules':FREQ_LABEL[f]}</button>`).join('')}</div><div class="chips" style="margin-top:8px"><button class="chip ${state.ui.taskAssignee==='all'?'active':''}" data-action="task-assignee" data-value="all">Everyone</button><button class="chip ${state.ui.taskAssignee==='shared'?'active':''}" data-action="task-assignee" data-value="shared">Shared</button>${state.household.members.map(m=>`<button class="chip ${state.ui.taskAssignee===m.id?'active':''}" data-action="task-assignee" data-value="${esc(m.id)}">${esc(m.emoji)} ${esc(m.name)}</button>`).join('')}</div></div>
  <div class="task-board">
    <section class="task-column"><h3>Scheduled <span class="badge">${groups.scheduled.length}</span></h3><div class="task-list">${groups.scheduled.length?groups.scheduled.sort(taskSort).map(t=>taskRow(t,today())).join(''):`<div class="empty">No scheduled items match.</div>`}</div></section>
    <section class="task-column"><h3>On demand <span class="badge">${groups.onDemand.length}</span></h3><div class="task-list">${groups.onDemand.length?groups.onDemand.sort(taskSort).map(t=>taskRow(t,today())).join(''):`<div class="empty">No on-demand items match.</div>`}</div></section>
    <section class="task-column"><h3>Completed today <span class="badge">${groups.completed.length}</span></h3><div class="task-list">${groups.completed.length?groups.completed.map(t=>taskRow(t,today())).join(''):`<div class="empty">Completed scheduled tasks appear here.</div>`}</div></section>
  </div>`;
}
function monthDates(monthStr){const [y,m]=monthStr.split('-').map(Number);const first=new Date(y,m-1,1),start=new Date(y,m-1,1-first.getDay()+Number(state.settings.startWeek||0));if(state.settings.startWeek===1&&first.getDay()===0)start.setDate(start.getDate()-7);return Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d})}
function eventsForDate(dateStr){return state.events.filter(e=>{if(e.date===dateStr)return true;if(e.frequency==='daily'&&e.startDate<=dateStr)return true;const d=parseDate(dateStr),s=parseDate(e.startDate||e.date);if(e.frequency==='weekly'&&e.startDate<=dateStr)return d.getDay()===s.getDay();if(e.frequency==='monthly'&&e.startDate<=dateStr)return d.getDate()===s.getDate();if(e.frequency==='annually'&&e.startDate<=dateStr)return d.getMonth()===s.getMonth()&&d.getDate()===s.getDate();return false}).sort((a,b)=>(a.time||'').localeCompare(b.time||''))}
function eventAgenda(e){return `<div class="agenda-item event"><strong>${e.time?esc(e.time)+' · ':''}${esc(e.title)}</strong><div class="tiny muted">${esc(e.category||'Event')}${e.assignee&&e.assignee!=='shared'?' · '+esc(member(e.assignee)?.name||''):''}</div></div>`}
function renderCalendar(){const dates=monthDates(state.ui.calendarMonth),sel=state.ui.selectedDate||today(),selTasks=tasksForDate(sel),selEvents=eventsForDate(sel),[y,m]=state.ui.calendarMonth.split('-').map(Number);const weekdays=state.settings.startWeek===1?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:DAY;return `${pageHead('Family calendar','Events, household schedules, care routines, and DBT / ADHD supports in one view.',`<button class="btn primary" data-open="event">＋ Event</button><button class="btn" data-open="task">＋ Task</button><button class="btn" onclick="window.print()">Print</button>`)}
  <div class="calendar-shell"><section class="card calendar-card"><div class="calendar-toolbar"><div class="actions"><button class="btn icon" data-action="month-prev" aria-label="Previous month">‹</button><button class="btn" data-action="month-today">Today</button><button class="btn icon" data-action="month-next" aria-label="Next month">›</button></div><h2>${MONTH[m-1]} ${y}</h2><span class="tiny muted">Tasks + events</span></div><div class="calendar-grid">${weekdays.map(w=>`<div class="weekday">${w}</div>`).join('')}${dates.map(d=>{const ds=ymd(d),items=[...eventsForDate(ds).map(e=>({title:e.title,kind:'event'})),...tasksForDate(ds).map(t=>({title:t.title,kind:'task'}))];return `<div class="day-cell ${d.getMonth()!==m-1?'other':''} ${ds===today()?'today':''} ${ds===sel?'selected':''}" data-action="select-day" data-date="${ds}"><button class="day-number" data-action="select-day" data-date="${ds}">${d.getDate()}</button><div class="cal-items">${items.slice(0,3).map(i=>`<div class="cal-chip ${i.kind}">${i.kind==='event'?'●':'✓'} ${esc(i.title)}</div>`).join('')}${items.length>3?`<div class="cal-more">+${items.length-3} more</div>`:''}</div></div>`}).join('')}</div></section>
  <aside class="calendar-side"><div class="card"><div class="card-head"><div><h2>${niceDate(sel,{weekday:'long',month:'long',day:'numeric'})}</h2><div class="tiny muted">Selected day</div></div><button class="btn small" data-open="event" data-date="${sel}">＋</button></div><h3>Events</h3><div class="agenda">${selEvents.length?selEvents.map(eventAgenda).join(''):`<div class="empty">No events.</div>`}</div><h3 style="margin-top:18px">Tasks</h3><div class="task-list">${selTasks.length?selTasks.map(t=>taskRow(t,sel,true)).join(''):`<div class="empty">No scheduled tasks.</div>`}</div></div><div class="card"><h3>Calendar legend</h3><p class="tiny"><span class="badge task">✓ Tasks</span> <span class="badge" style="border-left:3px solid var(--accent)">● Events</span></p><p class="tiny muted">On-demand tasks stay in their task area until logged and do not crowd every calendar day.</p></div></aside></div>`}
function noteCard(n){const preview=stripHtml(n.body||'').slice(0,220);return `<article class="card note-card ${n.pinned?'pinned':''} note-color-${esc(n.color||'none')}" data-action="open-note" data-id="${esc(n.id)}"><h3>${esc(n.title||'Untitled note')}</h3><div class="tiny muted">${esc(n.folder||'Notes')} · ${new Date(n.updatedAt||n.createdAt).toLocaleDateString()}</div><div class="note-preview">${esc(preview||'Empty note')}</div><div class="note-tags">${asArray(n.tags).map(t=>`<span class="badge">#${esc(t)}</span>`).join('')}${asArray(n.photoIds).length?`<span class="badge">📷 ${n.photoIds.length}</span>`:''}</div></article>`}
function renderNotes(){let notes=[...state.notes];const q=(state.ui.search||'').toLowerCase();if(q)notes=notes.filter(n=>`${n.title} ${stripHtml(n.body)} ${(n.tags||[]).join(' ')} ${n.folder||''}`.toLowerCase().includes(q));notes.sort((a,b)=>Number(b.pinned)-Number(a.pinned)||new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt));const folders=[...new Set(state.notes.map(n=>n.folder||'Notes'))];return `${pageHead('Notes','Apple Notes-style quick capture, rich text, tags, folders, pinning, checklists, and photo attachments.',`<button class="btn primary" data-open="note">＋ New note</button><button class="btn" data-action="export-notes">Export notes</button>`)}<div class="card flat" style="margin-bottom:14px"><div class="chips"><span class="chip active">All notes (${notes.length})</span>${folders.map(f=>`<span class="chip">📁 ${esc(f)}</span>`).join('')}</div></div>${notes.length?`<div class="note-grid">${notes.map(noteCard).join('')}</div>`:`<div class="empty">No notes yet. Use quick capture or create a rich note.</div>`}`}
function renderLists(){let lists=state.lists;const q=(state.ui.search||'').toLowerCase();if(q)lists=lists.filter(l=>`${l.title} ${l.items.map(i=>i.text).join(' ')}`.toLowerCase().includes(q));return `${pageHead('Shared lists','Groceries, supplies, packing, errands, and any checklist the household needs.',`<button class="btn primary" data-open="list">＋ New list</button>`)}${lists.length?`<div class="list-board">${lists.map(l=>`<section class="card list-card"><div class="card-head"><h2>${esc(l.icon||'📋')} ${esc(l.title)}</h2><div><span class="badge">${l.items.filter(i=>i.checked).length}/${l.items.length}</span><button class="btn small ghost" data-action="edit-list" data-id="${esc(l.id)}">•••</button></div></div><div class="list-items">${l.items.length?l.items.map(i=>`<div class="list-item ${i.checked?'checked':''}"><input type="checkbox" data-action="toggle-list-item" data-list="${esc(l.id)}" data-id="${esc(i.id)}" ${i.checked?'checked':''}><span class="list-text">${esc(i.text)}${i.quantity?` <span class="tiny muted">× ${esc(i.quantity)}</span>`:''}</span><button class="btn small ghost" data-action="delete-list-item" data-list="${esc(l.id)}" data-id="${esc(i.id)}">×</button></div>`).join(''):`<div class="empty">This list is empty.</div>`}</div><div class="list-add"><input class="input" data-list-input="${esc(l.id)}" placeholder="Add an item…"><button class="btn primary" data-action="add-list-item" data-id="${esc(l.id)}">＋</button></div></section>`).join('')}</div>`:`<div class="empty">No lists match.</div>`}`}
function renderPhotos(){let photos=[...state.photos].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));const q=(state.ui.search||'').toLowerCase();if(q)photos=photos.filter(p=>`${p.caption} ${p.status} ${state.tasks.find(t=>t.id===p.taskId)?.title||''}`.toLowerCase().includes(q));return `${pageHead('Progress photos','Capture incomplete, in-progress, or completed work. Photos are private to this browser unless backend sync succeeds.',`<button class="btn primary" data-action="photo-general">📷 Take photo</button>`)}${photos.length?`<div class="photo-grid">${photos.map(p=>{const t=state.tasks.find(t=>t.id===p.taskId);return `<article class="card photo-card"><div class="photo-wrap"><span class="photo-status">${p.status==='completed'?'Completed':p.status==='in_progress'?'In progress':'Incomplete'}</span><img data-photo-id="${esc(p.id)}" alt="${esc(p.caption||'Progress photo')}" loading="lazy"></div><div class="photo-info"><strong>${esc(t?.title||p.title||'Household progress')}</strong><div class="tiny muted">${niceDate(p.date)} · ${esc(member(p.memberId)?.name||'Household')}</div><p class="tiny">${esc(p.caption||'No caption')}</p><button class="btn small danger" data-action="delete-photo" data-id="${esc(p.id)}">Delete</button></div></article>`}).join('')}</div>`:`<div class="empty">No progress photos yet. Add one from a task or use the camera button.</div>`}`}
function renderRewards(){const householdTotal=state.household.members.reduce((s,m)=>s+(m.walletCopper||0),0);return `${pageHead('Rewards & currency','Every completion earns at least one copper. 10 copper = 1 silver, 10 silver = 1 gold, and 10 gold = 1 platinum.',`<button class="btn primary" data-action="add-reward">＋ Reward idea</button>`)}
  <section class="grid cols-3">${state.household.members.map(m=>`<div class="card wallet-card"><div class="card-head"><div><h2>${esc(m.emoji)} ${esc(m.name)}</h2><span class="tiny muted">Personal task wallet</span></div><strong>${formatCurrency(m.walletCopper||0,true)}</strong></div>${currencyCoins(m.walletCopper||0)}</div>`).join('')}<div class="card wallet-card"><div class="card-head"><div><h2>🏠 Household total</h2><span class="tiny muted">All member balances combined</span></div><strong>${formatCurrency(householdTotal,true)}</strong></div>${currencyCoins(householdTotal)}</div></section>
  <section class="grid cols-2" style="margin-top:16px"><div class="card"><div class="card-head"><h2>Reward ideas</h2><span class="tiny muted">Redeems from ${esc(member().name)}’s wallet</span></div><div class="task-list">${state.rewards.length?state.rewards.map(r=>`<div class="task-row"><div class="stat-icon">${esc(r.icon||'🎁')}</div><div><div class="task-title">${esc(r.title)}</div><div class="task-meta"><span class="reward">${formatCurrency(r.costCopper,true)}</span></div></div><div class="task-actions"><button class="btn small primary" data-action="redeem" data-id="${esc(r.id)}" ${currentWallet()<r.costCopper?'disabled':''}>Redeem</button><button class="btn small" data-action="edit-reward" data-id="${esc(r.id)}">Edit</button></div></div>`).join(''):`<div class="empty">Add household reward ideas.</div>`}</div></div><div class="card"><div class="card-head"><h2>Ledger</h2><span class="tiny muted">Most recent 50 entries</span></div><div class="ledger">${state.ledger.length?state.ledger.slice(0,50).map(x=>`<div class="ledger-row"><div><strong>${esc(x.description)}</strong><div class="tiny muted">${new Date(x.at).toLocaleString()} · ${esc(member(x.memberId)?.name||'Household')}</div></div><strong class="${x.amountCopper>=0?'positive':'negative'}">${x.amountCopper>=0?'+':'-'}${formatCurrency(Math.abs(x.amountCopper),true)}</strong></div>`).join(''):`<div class="empty">Complete a task to start the ledger.</div>`}</div></div></section>`}
function renderSettings(){const tab=state.ui.settingsTab||'household';const sourceData=[['OurSpace Retro Branding','Private project permission','Retro social-profile styling, brand handling, color wheels, background and logo uploads, and CRT controls'],['KashCal','Apache-2.0','Calendar recurrence and scheduling patterns'],['Family Organizer All-in-One','Apache-2.0','Household roles, chores, files, calendar, and allowance patterns'],['Family OS','MIT','Family-member-aware organization patterns'],['Weekaroo','MIT','Kitchen-dashboard, day notes, timers, and local-first patterns'],['Skylight MCP / API','MIT','Calendar, chores, lists, meals, photos, and rewards endpoint patterns'],['OurSpace Alarm Add-on','Private project permission','Reminder, photo progress, backend, and currency bridge patterns'],['CI Hackathon 2020 archive','No license found','Reviewed for general concepts only; no source copied']];return `${pageHead('Settings','Household members, appearance, data, reminders, sync, and source notices.',``)}<div class="settings-grid"><div class="card settings-menu">${[['household','Household'],['appearance','Appearance'],['data','Data & JSON'],['sync','Backend sync'],['reminders','Reminders'],['sources','Source notices']].map(([id,l])=>`<button class="btn ${tab===id?'primary':''}" data-action="settings-tab" data-value="${id}">${l}</button>`).join('')}</div><div class="card">
  <section class="settings-section ${tab==='household'?'active':''}" data-settings="household"><div class="card-head"><h2>Household members</h2><button class="btn small primary" data-action="add-member">＋ Member</button></div>${state.household.members.map(m=>`<div class="member-row"><div class="avatar" style="background:${esc(m.color)}">${esc(m.emoji||m.name[0])}</div><div><strong>${esc(m.name)}</strong>${m.nickname?`<div class="tiny muted">${esc(m.nickname)}</div>`:''}</div><span class="member-role tiny muted">${esc(m.role||'Member')}</span><button class="btn small" data-action="edit-member" data-id="${esc(m.id)}">Edit</button></div>`).join('')}<div class="field" style="margin-top:16px"><span>Household name</span><input id="householdName" value="${esc(state.household.name)}"><button class="btn" data-action="save-household-name">Save name</button></div></section>
  <section class="settings-section ${tab==='appearance'?'active':''}" data-settings="appearance"><h2>Appearance</h2><div class="form-grid"><div class="field"><span>Theme</span><select id="themeSetting"><option value="system" ${state.settings.theme==='system'?'selected':''}>Follow system</option><option value="light" ${state.settings.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Dark</option><option value="high" ${state.settings.theme==='high'?'selected':''}>High contrast</option></select></div><div class="field"><span>Text size</span><select id="textScaleSetting"><option value="0.9" ${state.settings.textScale==.9?'selected':''}>Compact</option><option value="1" ${state.settings.textScale==1?'selected':''}>Standard</option><option value="1.1" ${state.settings.textScale==1.1?'selected':''}>Large</option><option value="1.2" ${state.settings.textScale==1.2?'selected':''}>Extra large</option></select></div><div class="field"><span>Week starts on</span><select id="weekStartSetting"><option value="0" ${state.settings.startWeek===0?'selected':''}>Sunday</option><option value="1" ${state.settings.startWeek===1?'selected':''}>Monday</option></select></div></div><div class="actions" style="margin-top:14px"><button class="btn primary" data-action="save-appearance">Apply base accessibility</button><button class="btn accent" data-action="open-retro-appearance">Customize profile colors & background</button></div><p class="tiny muted">The profile designer stores its colors, optional background image, logo, and CRT strength in this browser.</p></section>
  <section class="settings-section ${tab==='data'?'active':''}" data-settings="data"><h2>Data & JSON</h2><p class="muted">Manual entry and JSON entry are equally supported. Imports can contain <code>tasks</code>, <code>care</code>, <code>dbt_adhd</code>, <code>events</code>, <code>notes</code>, <code>lists</code>, and <code>members</code>.</p><div class="actions"><button class="btn primary" data-action="import-open">Import JSON</button><button class="btn" data-action="export-all">Export backup</button><button class="btn" data-action="export-tasks">Export tasks</button><button class="btn danger" data-action="reset-data">Reset local data</button></div><details style="margin-top:16px"><summary>Accepted JSON structure</summary><pre class="code-box">${esc(JSON.stringify({tasks:[],care:[],dbt_adhd:[],events:[],notes:[],lists:[],members:[]},null,2))}</pre></details></section>
  <section class="settings-section ${tab==='sync'?'active':''}" data-settings="sync"><h2>Backend sync</h2><p class="muted">The app always saves locally first. When a valid OurSpace session token is detected, it can also use the locked Apps Script task, completion, proof, and wallet actions.</p><div class="actions"><button class="btn primary" data-action="sync-now">Sync now</button><button class="btn" data-action="test-backend">Test connection</button></div><div id="syncStatus" class="empty" style="margin-top:14px">No sync attempted this session.</div><details style="margin-top:16px"><summary>Technical endpoint details</summary><div class="code-box">Web app: ${esc(BACKEND.webApp)}\nLibrary: ${esc(BACKEND.library)}\nLibrary version: ${esc(BACKEND.libraryVersion)}</div></details></section>
  <section class="settings-section ${tab==='reminders'?'active':''}" data-settings="reminders"><h2>Reminders</h2><label class="check-row"><input type="checkbox" id="notificationSetting" ${state.settings.notifications?'checked':''}> Allow browser notifications while this page is running</label><label class="check-row" style="margin-top:10px"><input type="checkbox" id="soundSetting" ${state.settings.sound?'checked':''}> Play a gentle in-page sound for due reminders</label><button class="btn primary" style="margin-top:14px" data-action="save-reminders">Save reminder settings</button><p class="tiny muted">A single HTML page cannot guarantee alarms after the browser is fully closed. Overdue items are shown on the next open.</p></section>
  <section class="settings-section ${tab==='sources'?'active':''}" data-settings="sources"><h2>Source notices</h2><p class="muted">This single-file implementation was newly assembled from compatible patterns in the uploaded projects. It does not copy code from the unlicensed archive. Full license names are preserved here because the runtime has no external docs folder.</p><div class="source-list">${sourceData.map(s=>`<div class="source-item"><strong>${esc(s[0])}</strong><span class="tiny muted">${esc(s[1])}</span><div>${esc(s[2])}</div></div>`).join('')}</div><p class="tiny muted">Finch-specific pet and self-care progression were intentionally excluded. Apple Notes-style capture and organization concepts were used from the supplied research catalog.</p></section>
  </div></div>`}
function render(){renderChrome();const main=document.getElementById('householdMain');const routes={today:renderToday,calendar:renderCalendar,tasks:()=>renderTasks(),care:()=>renderTasks('care'),dbt:()=>renderTasks('dbt_adhd'),notes:renderNotes,lists:renderLists,photos:renderPhotos,rewards:renderRewards,settings:renderSettings};main.innerHTML=(routes[state.ui.route]||renderToday)();main.focus({preventScroll:true});hydratePhotos();}
function openModal(html,wide=false){if(modalCleanup){modalCleanup();modalCleanup=null}const back=document.getElementById('modalBackdrop'),modal=document.getElementById('modal');modal.className=`modal ${wide?'wide':''}`;modal.innerHTML=html;back.classList.add('open');back.setAttribute('aria-hidden','false');setTimeout(()=>modal.querySelector('input,textarea,select,button')?.focus(),0)}
function closeModal(){const back=document.getElementById('modalBackdrop');back.classList.remove('open');back.setAttribute('aria-hidden','true');if(modalCleanup){modalCleanup();modalCleanup=null}}
const modalShell=(title,body,foot='')=>`<div class="modal-head"><h2 id="modalTitle">${title}</h2><button class="close-modal" data-action="close-modal" aria-label="Close">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;
function taskModal(id=null,forcedType='task'){
  const t=state.tasks.find(x=>x.id===id)||{id:'',title:'',type:forcedType,description:'',frequency:'on_demand',rewardCopper:5,assignee:'shared',priority:'medium',tags:[],reminder:false,time:'',weekdays:[],dayOfMonth:1,month:1,active:true};
  openModal(modalShell(t.id?'Edit task':'Add task',`<form id="taskForm" class="form-grid"><input type="hidden" name="id" value="${esc(t.id)}"><div class="field span-2"><span>Title</span><input name="title" required maxlength="160" value="${esc(t.title)}" placeholder="What needs to happen?"></div><div class="field"><span>Area</span><select name="type"><option value="task" ${t.type==='task'?'selected':''}>Task</option><option value="care" ${t.type==='care'?'selected':''}>Care</option><option value="dbt_adhd" ${t.type==='dbt_adhd'?'selected':''}>DBT / ADHD</option></select></div><div class="field"><span>Schedule</span><select name="frequency" id="taskFrequencySelect">${Object.entries(FREQ_LABEL).map(([k,v])=>`<option value="${k}" ${t.frequency===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><span>Assigned to</span><select name="assignee">${memberOptions(t.assignee)}</select></div><div class="field"><span>Priority</span><select name="priority"><option value="low" ${t.priority==='low'?'selected':''}>Low</option><option value="medium" ${t.priority==='medium'?'selected':''}>Medium</option><option value="high" ${t.priority==='high'?'selected':''}>High</option></select></div><div class="field"><span>Reward in total copper</span><input name="rewardCopper" type="number" min="1" max="999999" value="${Math.max(1,t.rewardCopper||1)}"><small class="muted">At least 1 copper; automatically converted for display.</small></div><div class="field"><span>Reminder time</span><input name="time" type="time" value="${esc(t.time||'')}"></div><div class="field span-2 schedule-weekly"><span>Weekly days</span><div class="weekday-picks">${DAY.map((d,i)=>`<label><input type="checkbox" name="weekdays" value="${i}" ${t.weekdays?.includes(i)?'checked':''}><span>${d[0]}</span></label>`).join('')}</div></div><div class="field schedule-monthly schedule-annually"><span>Day of month</span><input name="dayOfMonth" type="number" min="1" max="31" value="${t.dayOfMonth||1}"></div><div class="field schedule-annually"><span>Month</span><select name="month">${MONTH.map((x,i)=>`<option value="${i+1}" ${Number(t.month||1)===i+1?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span-2"><span>Instructions or notes</span><textarea name="description" placeholder="Optional details, steps, or care instructions…">${esc(t.description||'')}</textarea></div><div class="field span-2"><span>Tags (comma-separated)</span><input name="tags" value="${esc((t.tags||[]).join(', '))}" placeholder="kitchen, shared, low-energy"></div><label class="check-row"><input name="reminder" type="checkbox" ${t.reminder?'checked':''}> Use reminder when a time is set</label><label class="check-row"><input name="active" type="checkbox" ${t.active!==false?'checked':''}> Active</label></form>`,`${t.id?`<button class="btn danger" data-action="delete-task" data-id="${esc(t.id)}">Delete</button>`:''}<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-task">Save task</button>`));
  const freq=document.getElementById('taskFrequencySelect');const update=()=>{document.querySelectorAll('[class*="schedule-"]').forEach(el=>{if(el.classList.contains('field'))el.style.display='none'});document.querySelectorAll(`.schedule-${freq.value}`).forEach(el=>el.style.display='grid')};freq.addEventListener('change',()=>{const reward=document.querySelector('[name=rewardCopper]');if(reward&&!t.id)reward.value=DEFAULT_REWARD[freq.value]||10;update()});update();
}
function eventModal(id=null,date=today()){
  const e=state.events.find(x=>x.id===id)||{id:'',title:'',date,startDate:date,time:'',endTime:'',allDay:false,category:'Family',assignee:'shared',frequency:'none',location:'',notes:''};
  openModal(modalShell(e.id?'Edit event':'Add event',`<form id="eventForm" class="form-grid"><input type="hidden" name="id" value="${esc(e.id)}"><div class="field span-2"><span>Event title</span><input name="title" required value="${esc(e.title)}"></div><div class="field"><span>Date</span><input name="date" type="date" required value="${esc(e.date||date)}"></div><div class="field"><span>Repeats</span><select name="frequency"><option value="none" ${e.frequency==='none'?'selected':''}>Does not repeat</option><option value="daily" ${e.frequency==='daily'?'selected':''}>Daily</option><option value="weekly" ${e.frequency==='weekly'?'selected':''}>Weekly</option><option value="monthly" ${e.frequency==='monthly'?'selected':''}>Monthly</option><option value="annually" ${e.frequency==='annually'?'selected':''}>Annually</option></select></div><div class="field"><span>Start time</span><input name="time" type="time" value="${esc(e.time||'')}"></div><div class="field"><span>End time</span><input name="endTime" type="time" value="${esc(e.endTime||'')}"></div><div class="field"><span>Category</span><select name="category"><option>Family</option><option>Appointment</option><option>Meal</option><option>School</option><option>Work</option><option>Birthday</option><option>Care</option><option>Other</option></select></div><div class="field"><span>For</span><select name="assignee">${memberOptions(e.assignee)}</select></div><div class="field span-2"><span>Location</span><input name="location" value="${esc(e.location||'')}"></div><div class="field span-2"><span>Notes</span><textarea name="notes">${esc(e.notes||'')}</textarea></div></form>`,`${e.id?`<button class="btn danger" data-action="delete-event" data-id="${esc(e.id)}">Delete</button>`:''}<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-event">Save event</button>`));
  const cat=document.querySelector('#eventForm [name=category]');cat.value=e.category||'Family';
}
function noteModal(id=null){
  const n=state.notes.find(x=>x.id===id)||{id:'',title:'',body:'',folder:'Notes',tags:[],pinned:false,color:'none',photoIds:[],createdAt:nowIso()};
  openModal(modalShell(n.id?'Edit note':'New note',`<form id="noteForm" class="form-grid"><input type="hidden" name="id" value="${esc(n.id)}"><div class="field span-2"><span>Title</span><input name="title" value="${esc(n.title)}" placeholder="Untitled note"></div><div class="field"><span>Folder</span><input name="folder" list="folderList" value="${esc(n.folder||'Notes')}"><datalist id="folderList">${[...new Set(state.notes.map(x=>x.folder||'Notes'))].map(f=>`<option value="${esc(f)}">`).join('')}</datalist></div><div class="field"><span>Color</span><select name="color"><option value="none">Standard</option><option value="yellow">Yellow</option><option value="blue">Blue</option><option value="green">Green</option><option value="pink">Pink</option></select></div><div class="field span-2"><span>Tags (comma-separated)</span><input name="tags" value="${esc((n.tags||[]).join(', '))}"></div><label class="check-row span-2"><input name="pinned" type="checkbox" ${n.pinned?'checked':''}> Pin this note</label><div class="span-2"><div class="editor-toolbar"><button type="button" data-editor="bold"><b>B</b></button><button type="button" data-editor="italic"><i>I</i></button><button type="button" data-editor="underline"><u>U</u></button><button type="button" data-editor="strikeThrough"><s>S</s></button><button type="button" data-editor="insertUnorderedList">• List</button><button type="button" data-editor="insertOrderedList">1. List</button><button type="button" data-editor="formatBlock" data-value="h2">Heading</button><button type="button" data-action="insert-checklist">☑ Checklist</button></div><div id="noteEditor" class="note-editor" contenteditable="true" role="textbox" aria-multiline="true">${sanitizeHTML(n.body||'')}</div></div><div class="field span-2"><span>Attach photos (optional)</span><input id="notePhotoInput" type="file" accept="image/*" capture="environment" multiple><small class="muted">Images are resized and stored locally. Existing attachments: ${n.photoIds?.length||0}</small></div></form>`,`${n.id?`<button class="btn danger" data-action="delete-note" data-id="${esc(n.id)}">Delete</button>`:''}<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-note">Save note</button>`),true);
  document.querySelector('#noteForm [name=color]').value=n.color||'none';
}
function listModal(id=null){const l=state.lists.find(x=>x.id===id)||{id:'',title:'',icon:'📋',color:'none',items:[]};openModal(modalShell(l.id?'Edit list':'New list',`<form id="listForm" class="form-grid"><input type="hidden" name="id" value="${esc(l.id)}"><div class="field span-2"><span>List title</span><input name="title" required value="${esc(l.title)}"></div><div class="field"><span>Icon</span><input name="icon" maxlength="4" value="${esc(l.icon||'📋')}"></div><div class="field"><span>Color label</span><select name="color"><option value="none">Standard</option><option value="green">Green</option><option value="blue">Blue</option><option value="yellow">Yellow</option><option value="pink">Pink</option></select></div></form>`,`${l.id?`<button class="btn danger" data-action="delete-list" data-id="${esc(l.id)}">Delete</button>`:''}<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-list">Save list</button>`));document.querySelector('#listForm [name=color]').value=l.color||'none'}
function photoModal(taskId=null){const task=state.tasks.find(t=>t.id===taskId);openModal(modalShell('Add progress photo',`<form id="photoForm" class="form-grid"><input type="hidden" name="taskId" value="${esc(taskId||'')}"><div class="field span-2"><span>Photo</span><input id="photoInput" type="file" accept="image/*" capture="environment" required><div class="dropzone" id="photoPreview">Tap the file control to take a picture or choose one.</div></div><div class="field"><span>Progress shown</span><select name="status"><option value="incomplete">Incomplete / before</option><option value="in_progress">In progress</option><option value="completed">Completed / after</option></select></div><div class="field"><span>Date</span><input name="date" type="date" value="${today()}"></div><div class="field span-2"><span>Caption</span><input name="caption" value="${esc(task?.title||'')}" placeholder="What does this photo show?"></div><label class="check-row span-2"><input name="completeTask" type="checkbox"> Also mark this task complete and award currency</label><p class="tiny muted span-2">A photo is never required to complete a task. This attachment is optional context only.</p></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-photo">Save photo</button>`));const inp=document.getElementById('photoInput');inp.addEventListener('change',async()=>{if(!inp.files[0])return;const data=await imageToDataUrl(inp.files[0],900,.8);document.getElementById('photoPreview').innerHTML=`<img src="${data}" alt="Preview" style="max-width:100%;max-height:260px;border-radius:0px">`;document.getElementById('photoPreview').dataset.preview=data})}
function memberModal(id=null){const m=state.household.members.find(x=>x.id===id)||{id:'',name:'',nickname:'',emoji:'🙂',color:'#336699',role:'Member',walletCopper:0};openModal(modalShell(m.id?'Edit member':'Add member',`<form id="memberForm" class="form-grid"><input type="hidden" name="id" value="${esc(m.id)}"><div class="field"><span>Name</span><input name="name" required value="${esc(m.name)}"></div><div class="field"><span>Nickname</span><input name="nickname" value="${esc(m.nickname||'')}"></div><div class="field"><span>Emoji</span><input name="emoji" maxlength="4" value="${esc(m.emoji||'🙂')}"></div><div class="field"><span>Color</span><input name="color" type="color" value="${esc(m.color||'#336699')}"></div><div class="field"><span>Role label</span><input name="role" value="${esc(m.role||'Member')}"></div><div class="field"><span>Starting / adjusted balance in copper</span><input name="walletCopper" type="number" min="0" value="${m.walletCopper||0}"></div></form>`,`${m.id&&state.household.members.length>1?`<button class="btn danger" data-action="delete-member" data-id="${esc(m.id)}">Delete</button>`:''}<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-member">Save member</button>`))}
function rewardModal(id=null){const r=state.rewards.find(x=>x.id===id)||{id:'',title:'',costCopper:25,icon:'🎁'};openModal(modalShell(r.id?'Edit reward':'Add reward idea',`<form id="rewardForm" class="form-grid"><input type="hidden" name="id" value="${esc(r.id)}"><div class="field span-2"><span>Reward</span><input name="title" required value="${esc(r.title)}"></div><div class="field"><span>Icon</span><input name="icon" maxlength="4" value="${esc(r.icon||'🎁')}"></div><div class="field"><span>Cost in total copper</span><input name="costCopper" type="number" min="1" value="${r.costCopper||25}"></div></form>`,`${r.id?`<button class="btn danger" data-action="delete-reward" data-id="${esc(r.id)}">Delete</button>`:''}<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-reward">Save reward</button>`))}
function importModal(){openModal(modalShell('Import JSON',`<div class="form-grid"><div class="field span-2"><span>Choose a JSON file</span><input id="jsonFile" type="file" accept="application/json,.json"></div><div class="field span-2"><span>Or paste JSON</span><textarea id="jsonText" style="min-height:260px" placeholder='{"tasks":[...]}'></textarea></div><label class="check-row span-2"><input id="replaceImport" type="checkbox"> Replace existing matching sections instead of merging</label><div class="span-2 tiny muted">Accepted top-level keys: tasks, care, dbt_adhd, events, notes, lists, members, rewards. A root array is treated as tasks.</div></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="run-import">Import</button>`),true);document.getElementById('jsonFile').addEventListener('change',async e=>{const f=e.target.files[0];if(f)document.getElementById('jsonText').value=await f.text()})}
function completeTask(taskId,dateStr=today()){
  const t=state.tasks.find(x=>x.id===taskId);if(!t)return;const existing=completionsFor(taskId,dateStr);if(t.frequency!=='on_demand'&&existing.length){undoCompletion(existing[0].id);return}
  const c={id:uid('completion'),taskId,date:dateStr,occurrenceKey:t.frequency==='on_demand'?`${dateStr}#${Date.now()}`:dateStr,completedAt:nowIso(),memberId:state.currentMemberId,rewardCopper:Math.max(1,Number(t.rewardCopper)||1)};state.completions.push(c);changeWallet(c.memberId,c.rewardCopper,`Completed: ${t.title}`,'task_completion',c.id);logActivity(`${member(c.memberId).name} completed “${t.title}” and earned ${formatCurrency(c.rewardCopper)}.`,'completion');save();backendRequest('onyx.task.complete',{taskId:t.id,dueKey:c.occurrenceKey,completedAt:c.completedAt,profileKey:c.memberId,rewardCopper:c.rewardCopper}).catch(()=>{});toast(`Completed! +${formatCurrency(c.rewardCopper)}`,'success');render();}
function undoCompletion(completionId){const c=state.completions.find(x=>x.id===completionId);if(!c||c.undoneAt)return;c.undoneAt=nowIso();const t=state.tasks.find(x=>x.id===c.taskId);changeWallet(c.memberId,-c.rewardCopper,`Undid: ${t?.title||'task'}`,'task_undo',c.id);logActivity(`${member(c.memberId)?.name||'A member'} undid “${t?.title||'a task'}”; reward was removed.`,'undo');save();toast('Completion undone and reward removed.');render()}
function changeWallet(memberId,amount,description,type,refId=''){const m=member(memberId);const before=m.walletCopper||0;m.walletCopper=Math.max(0,before+amount);const actual=m.walletCopper-before;state.ledger.unshift({id:uid('ledger'),memberId,amountCopper:actual,description,type,refId,at:nowIso()});}
async function saveTask(){const f=document.getElementById('taskForm');if(!f.reportValidity())return;const fd=new FormData(f),id=fd.get('id')||uid('task');const existing=state.tasks.find(t=>t.id===id);const t={id,title:String(fd.get('title')).trim(),type:fd.get('type'),description:String(fd.get('description')||'').trim(),frequency:fd.get('frequency'),rewardCopper:Math.max(1,Math.floor(Number(fd.get('rewardCopper'))||1)),assignee:fd.get('assignee'),priority:fd.get('priority'),tags:String(fd.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean),reminder:fd.has('reminder'),active:fd.has('active'),time:fd.get('time')||'',weekdays:fd.getAll('weekdays').map(Number),dayOfMonth:clamp(Number(fd.get('dayOfMonth')||1),1,31),month:clamp(Number(fd.get('month')||1),1,12),createdAt:existing?.createdAt||nowIso(),updatedAt:nowIso()};if(existing)Object.assign(existing,t);else state.tasks.push(t);logActivity(`${existing?'Updated':'Added'} ${TYPE_META[t.type].label.toLowerCase()} “${t.title}”.`);save();closeModal();render();toast('Task saved.','success');backendRequest('onyx.task.upsert',{taskId:t.id,title:t.title,category:TYPE_META[t.type].label,assignedProfile:t.assignee,frequency:t.frequency,rewardCopper:t.rewardCopper,requiresPhoto:false,verificationMode:'optional-photo',active:t.active,description:t.description,schedule:{timeOfDay:t.time,weekdays:t.weekdays,dayOfMonth:t.dayOfMonth,month:t.month,date:''}}).catch(()=>{})}
function saveEvent(){const f=document.getElementById('eventForm');if(!f.reportValidity())return;const fd=new FormData(f),id=fd.get('id')||uid('event'),existing=state.events.find(x=>x.id===id);const e={id,title:String(fd.get('title')).trim(),date:fd.get('date'),startDate:fd.get('date'),frequency:fd.get('frequency'),time:fd.get('time')||'',endTime:fd.get('endTime')||'',category:fd.get('category'),assignee:fd.get('assignee'),location:String(fd.get('location')||'').trim(),notes:String(fd.get('notes')||'').trim(),createdAt:existing?.createdAt||nowIso(),updatedAt:nowIso()};if(existing)Object.assign(existing,e);else state.events.push(e);logActivity(`${existing?'Updated':'Added'} calendar event “${e.title}”.`);save();closeModal();render();toast('Event saved.','success')}
async function saveNote(){const f=document.getElementById('noteForm');const fd=new FormData(f),id=fd.get('id')||uid('note'),existing=state.notes.find(x=>x.id===id);const photoIds=[...(existing?.photoIds||[])];const files=document.getElementById('notePhotoInput').files;for(const file of files){const pid=uid('photo');const dataUrl=await imageToDataUrl(file,1100,.82);await photoDB.put(pid,dataUrl);state.photos.push({id:pid,title:fd.get('title')||'Note attachment',caption:`Attached to note: ${fd.get('title')||'Untitled'}`,status:'in_progress',date:today(),memberId:state.currentMemberId,noteId:id,createdAt:nowIso()});photoIds.push(pid)}const n={id,title:String(fd.get('title')||'').trim()||'Untitled note',body:sanitizeHTML(document.getElementById('noteEditor').innerHTML),folder:String(fd.get('folder')||'Notes').trim()||'Notes',tags:String(fd.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean),pinned:fd.has('pinned'),color:fd.get('color'),photoIds,createdAt:existing?.createdAt||nowIso(),updatedAt:nowIso()};if(existing)Object.assign(existing,n);else state.notes.push(n);logActivity(`${existing?'Updated':'Created'} note “${n.title}”.`);save();closeModal();render();toast('Note saved.','success')}
function saveList(){const f=document.getElementById('listForm');if(!f.reportValidity())return;const fd=new FormData(f),id=fd.get('id')||uid('list'),existing=state.lists.find(x=>x.id===id);const l={id,title:String(fd.get('title')).trim(),icon:String(fd.get('icon')||'📋').trim(),color:fd.get('color'),items:existing?.items||[],createdAt:existing?.createdAt||nowIso(),updatedAt:nowIso()};if(existing)Object.assign(existing,l);else state.lists.push(l);logActivity(`${existing?'Updated':'Created'} list “${l.title}”.`);save();closeModal();render();toast('List saved.','success')}
async function savePhoto(){const f=document.getElementById('photoForm');if(!f.reportValidity())return;const fd=new FormData(f),file=document.getElementById('photoInput').files[0];if(!file)return toast('Choose a photo.','error');const id=uid('photo'),dataUrl=document.getElementById('photoPreview').dataset.preview||await imageToDataUrl(file,900,.8);await photoDB.put(id,dataUrl);const p={id,taskId:fd.get('taskId')||'',title:'Household progress',caption:String(fd.get('caption')||'').trim(),status:fd.get('status'),date:fd.get('date')||today(),memberId:state.currentMemberId,createdAt:nowIso(),mimeType:'image/jpeg',name:file.name||'progress.jpg'};state.photos.push(p);logActivity(`${member().name} added a ${p.status.replace('_',' ')} progress photo${p.taskId?' for “'+(state.tasks.find(t=>t.id===p.taskId)?.title||'task')+'”':''}.`,'photo');save();if(fd.has('completeTask')&&p.taskId){closeModal();completeTask(p.taskId,p.date)}else{closeModal();render();toast('Progress photo saved.','success')}backendRequest('onyx.task.proof.submit',{profileKey:p.memberId,taskId:p.taskId,dueKey:p.date,completedAt:p.createdAt,caption:p.caption,verificationMode:'optional-photo',photo:{dataUrl,mimeType:p.mimeType,name:p.name},progressState:p.status}).catch(()=>{})}
function saveMember(){const f=document.getElementById('memberForm');if(!f.reportValidity())return;const fd=new FormData(f),id=fd.get('id')||uid('member'),existing=state.household.members.find(x=>x.id===id),oldBalance=existing?.walletCopper||0;const m={id,name:String(fd.get('name')).trim(),nickname:String(fd.get('nickname')||'').trim(),emoji:String(fd.get('emoji')||'🙂').trim(),color:fd.get('color')||'#336699',role:String(fd.get('role')||'Member').trim(),walletCopper:Math.max(0,Math.floor(Number(fd.get('walletCopper'))||0))};if(existing){Object.assign(existing,m);const delta=m.walletCopper-oldBalance;if(delta)state.ledger.unshift({id:uid('ledger'),memberId:id,amountCopper:delta,description:'Manual balance adjustment',type:'adjustment',at:nowIso()})}else state.household.members.push(m);save();closeModal();render();toast('Member saved.','success')}
function saveReward(){const f=document.getElementById('rewardForm');if(!f.reportValidity())return;const fd=new FormData(f),id=fd.get('id')||uid('reward'),existing=state.rewards.find(x=>x.id===id);const r={id,title:String(fd.get('title')).trim(),icon:String(fd.get('icon')||'🎁').trim(),costCopper:Math.max(1,Math.floor(Number(fd.get('costCopper'))||1))};if(existing)Object.assign(existing,r);else state.rewards.push(r);save();closeModal();render();toast('Reward saved.','success')}
async function imageToDataUrl(file,max=1000,quality=.8){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{let w=img.width,h=img.height;if(Math.max(w,h)>max){const scale=max/Math.max(w,h);w=Math.round(w*scale);h=Math.round(h*scale)}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);resolve(c.toDataURL('image/jpeg',quality))};img.src=reader.result};reader.readAsDataURL(file)})}
const photoDB={db:null,async open(){if(this.db)return this.db;this.db=await new Promise((res,rej)=>{const r=indexedDB.open('OurSpaceHouseholdOrganizer',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('photos'))r.result.createObjectStore('photos')};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});return this.db},async put(id,data){const db=await this.open();return new Promise((res,rej)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').put(data,id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})},async get(id){try{const db=await this.open();return await new Promise((res,rej)=>{const r=db.transaction('photos').objectStore('photos').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}catch{return null}},async del(id){try{const db=await this.open();return new Promise((res,rej)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').delete(id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}catch{}}};
async function hydratePhotos(){for(const img of document.querySelectorAll('img[data-photo-id]')){const data=await photoDB.get(img.dataset.photoId);img.src=data||'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="640" height="480"><rect width="100%" height="100%" fill="#d5e8fb"/><text x="50%" y="50%" text-anchor="middle" fill="#336699" font-family="sans-serif">Photo unavailable</text></svg>`)}}
function download(filename,text,type='application/json'){const blob=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function normalizeFrequency(v){v=String(v||'on_demand').toLowerCase().replace(/[- ]/g,'_');if(['annual','yearly','year'].includes(v))return'annually';if(['once','one_time','anytime','as_needed'].includes(v))return'on_demand';return FREQ_LABEL[v]?v:'on_demand'}
function normalizeImportedTask(obj,type='task'){return{id:String(obj.id||obj.key||uid('task')),title:String(obj.title||obj.name||'').trim(),type:TYPE_META[obj.type]?obj.type:type,description:String(obj.description||obj.notes||''),frequency:normalizeFrequency(obj.frequency||obj.recurrence||'on_demand'),rewardCopper:Math.max(1,Math.floor(Number(obj.rewardCopper??obj.reward_copper??DEFAULT_REWARD[normalizeFrequency(obj.frequency)]??10))),assignee:String(obj.assignee||obj.assignedProfile||'shared'),priority:['low','medium','high'].includes(obj.priority)?obj.priority:'medium',tags:asArray(obj.tags),reminder:Boolean(obj.reminder),time:String(obj.time||obj.timeOfDay||obj.schedule?.timeOfDay||''),weekdays:asArray(obj.weekdays||obj.schedule?.weekdays).map(Number),dayOfMonth:Number(obj.dayOfMonth||obj.schedule?.dayOfMonth||1),month:Number(obj.month||obj.schedule?.month||1),active:obj.active!==false,createdAt:obj.createdAt||nowIso(),updatedAt:nowIso()}}
function mergeById(current,incoming,replace=false){if(replace)return incoming;const map=new Map(current.map(x=>[x.id,x]));incoming.forEach(x=>map.set(x.id,map.has(x.id)?{...map.get(x.id),...x}:x));return[...map.values()]}
function runImport(){try{let obj=JSON.parse(document.getElementById('jsonText').value);if(Array.isArray(obj))obj={tasks:obj};const replace=document.getElementById('replaceImport').checked;const tasks=[...asArray(obj.tasks).map(x=>normalizeImportedTask(x,'task')),...asArray(obj.care).map(x=>normalizeImportedTask(x,'care')),...asArray(obj.dbt_adhd).map(x=>normalizeImportedTask(x,'dbt_adhd'))].filter(x=>x.title);if(tasks.length)state.tasks=mergeById(state.tasks,tasks,replace);if(obj.events)state.events=mergeById(state.events,asArray(obj.events).map(e=>({...e,id:e.id||uid('event'),date:e.date||e.startDate||today(),startDate:e.startDate||e.date||today(),frequency:e.frequency||'none',createdAt:e.createdAt||nowIso()})),replace);if(obj.notes)state.notes=mergeById(state.notes,asArray(obj.notes).map(n=>({...n,id:n.id||uid('note'),body:sanitizeHTML(n.body||n.text||''),title:n.title||'Untitled note',createdAt:n.createdAt||nowIso(),updatedAt:nowIso()})),replace);if(obj.lists)state.lists=mergeById(state.lists,asArray(obj.lists).map(l=>({...l,id:l.id||uid('list'),items:asArray(l.items).map(i=>typeof i==='string'?{id:uid('item'),text:i,checked:false}:{id:i.id||uid('item'),...i}),createdAt:l.createdAt||nowIso()})),replace);if(obj.rewards)state.rewards=mergeById(state.rewards,asArray(obj.rewards).map(r=>({...r,id:r.id||uid('reward'),costCopper:Math.max(1,Number(r.costCopper)||25)})),replace);if(obj.members){const mem=asArray(obj.members).map(m=>({...m,id:m.id||uid('member'),name:m.name||'Member',walletCopper:Math.max(0,Number(m.walletCopper)||0)}));state.household.members=mergeById(state.household.members,mem,replace)}logActivity(`Imported JSON: ${tasks.length} task entries plus supplied household data.`,'import');save();closeModal();render();toast(`Imported ${tasks.length} task entries and related data.`,'success')}catch(e){toast(`Import failed: ${e.message}`,'error')}}
function sessionToken(){return window.OURSPACE_SESSION_TOKEN||window.OurSpaceSession?.token||window.OurSpaceAuth?.sessionToken||localStorage.getItem('ourspace_session_token')||localStorage.getItem('ourspaceSessionToken')||sessionStorage.getItem('ourspace_session_token')||''}
async function backendRequest(action,data={}){const token=sessionToken();if(!token)throw new Error('No OurSpace session token was found. Local mode remains active.');const body={action,sessionToken:token,data:{profileKey:state.currentMemberId,clientModule:'OurSpaceHouseholdOrganizer',clientVersion:APP_VERSION,...data}};const res=await fetch(BACKEND.webApp,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(body)});if(!res.ok)throw new Error(`Backend returned ${res.status}`);const text=await res.text();try{return JSON.parse(text)}catch{return{text}}}
async function syncNow(testOnly=false){const box=document.getElementById('syncStatus');if(box)box.textContent='Connecting…';try{const home=await backendRequest('onyx.care.home',{});if(testOnly){if(box)box.innerHTML=`<strong>Connected.</strong><div class="tiny muted">${esc(home?.message||'Backend responded successfully.')}</div>`;toast('Backend connection succeeded.','success');return}const remote=await backendRequest('onyx.task.list',{});const raw=remote?.data?.tasks||remote?.tasks||remote?.data||[];if(Array.isArray(raw)&&raw.length){const incoming=raw.map(x=>normalizeImportedTask({...x,type:x.type||(/care/i.test(x.category||'')?'care':/dbt|adhd/i.test(x.category||'')?'dbt_adhd':'task')}));state.tasks=mergeById(state.tasks,incoming,false)}try{const wallet=await backendRequest('onyx.wallet.balance',{});const total=Number(wallet?.data?.totalCopper??wallet?.totalCopper);if(Number.isFinite(total))member().walletCopper=Math.max(0,total)}catch{}save();render();toast('Backend sync completed.','success')}catch(e){if(box)box.innerHTML=`<strong>Local mode active.</strong><div class="tiny muted">${esc(e.message)}</div>`;toast(e.message,'error')}}
function quickFocus(){const candidates=tasksForDate(today()).filter(t=>!isCompleted(t,today()));if(!candidates.length)return toast('Nothing scheduled remains today.','success');const t=candidates.sort(taskSort)[0];openModal(modalShell('One next step',`<div style="text-align:center;padding:16px"><div style="font-size:3rem">${TYPE_META[t.type].icon}</div><h2>${esc(t.title)}</h2><p class="muted">${esc(t.description||'Open the task and do the smallest useful next step.')}</p><p class="reward">Earn ${formatCurrency(t.rewardCopper)}</p></div>`,`<button class="btn" data-action="close-modal">Not now</button><button class="btn primary" data-action="complete-focus" data-id="${esc(t.id)}">Mark complete</button>`))}
function playTone(){if(!state.settings.sound)return;try{const ac=new(window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.frequency.value=523;g.gain.setValueAtTime(.0001,ac.currentTime);g.gain.exponentialRampToValueAtTime(.12,ac.currentTime+.03);g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+.35);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.4)}catch{}}
const notified=new Set();function checkReminders(){if(!state.settings.notifications&&!state.settings.sound)return;const now=new Date(),date=today(),hh=`${pad(now.getHours())}:${pad(now.getMinutes())}`;state.tasks.filter(t=>t.reminder&&t.time&&isDue(t,date)&&!isCompleted(t,date)&&t.time<=hh).forEach(t=>{const key=`${t.id}:${date}`;if(notified.has(key))return;notified.add(key);playTone();if(state.settings.notifications&&Notification.permission==='granted')new Notification(`Due: ${t.title}`,{body:`Worth ${formatCurrency(t.rewardCopper)}. Photo proof is optional.`});toast(`Reminder: ${t.title}`)})}
function addListItem(listId){const input=document.querySelector(`[data-list-input="${CSS.escape(listId)}"]`),text=input?.value.trim();if(!text)return;const l=state.lists.find(x=>x.id===listId);l.items.push({id:uid('item'),text,quantity:'',checked:false,addedBy:state.currentMemberId,createdAt:nowIso()});input.value='';save(false);render()}
async function deletePhoto(id){if(!confirm('Delete this progress photo?'))return;state.photos=state.photos.filter(p=>p.id!==id);state.notes.forEach(n=>n.photoIds=asArray(n.photoIds).filter(x=>x!==id));await photoDB.del(id);save();render();toast('Photo deleted.')}
function handleClick(e){const el=e.target.closest('[data-action],[data-route],[data-open]');if(!el)return;if(el.dataset.route){route(el.dataset.route);return}if(el.dataset.open){if(el.dataset.open==='task')taskModal(null,el.dataset.type||'task');if(el.dataset.open==='event')eventModal(null,el.dataset.date||state.ui.selectedDate||today());if(el.dataset.open==='note')noteModal();if(el.dataset.open==='list')listModal();document.getElementById('fabMenu').classList.remove('open');return}const a=el.dataset.action,id=el.dataset.id;
  if(a==='close-modal')closeModal();
  else if(a==='toggle-task')completeTask(id,el.dataset.date||today());
  else if(a==='edit-task')taskModal(id);
  else if(a==='delete-task'&&confirm('Delete this task?')){state.tasks=state.tasks.filter(t=>t.id!==id);save();closeModal();render()}
  else if(a==='save-task')saveTask();
  else if(a==='photo-task')photoModal(id);
  else if(a==='photo-general')photoModal();
  else if(a==='save-photo')savePhoto();
  else if(a==='delete-photo')deletePhoto(id);
  else if(a==='start-day'){state.dayStarts[today()]=state.dayStarts[today()]||nowIso();logActivity(`${member().name} started the day.`);save();render();toast('Day started. Begin wherever you can.','success')}
  else if(a==='quick-focus')quickFocus();
  else if(a==='complete-focus'){closeModal();completeTask(id)}
  else if(a==='quick-note'){const inp=document.getElementById('quickNoteInput');if(!inp.value.trim())return;state.notes.unshift({id:uid('note'),title:inp.value.trim().slice(0,80),body:`<p>${esc(inp.value.trim())}</p>`,folder:'Quick Notes',tags:[],pinned:false,color:'none',photoIds:[],createdAt:nowIso(),updatedAt:nowIso()});logActivity(`${member().name} added a quick note.`);save();render();toast('Quick note saved.','success')}
  else if(a==='task-freq'){state.ui.taskFrequency=el.dataset.value;save(false);render()}
  else if(a==='task-assignee'){state.ui.taskAssignee=el.dataset.value;save(false);render()}
  else if(a==='month-prev'||a==='month-next'){let [y,m]=state.ui.calendarMonth.split('-').map(Number);m+=a==='month-prev'?-1:1;const d=new Date(y,m-1,1);state.ui.calendarMonth=`${d.getFullYear()}-${pad(d.getMonth()+1)}`;save(false);render()}
  else if(a==='month-today'){state.ui.calendarMonth=today().slice(0,7);state.ui.selectedDate=today();save(false);render()}
  else if(a==='select-day'){state.ui.selectedDate=el.dataset.date;state.ui.calendarMonth=el.dataset.date.slice(0,7);save(false);render()}
  else if(a==='save-event')saveEvent();
  else if(a==='delete-event'&&confirm('Delete this event?')){state.events=state.events.filter(x=>x.id!==id);save();closeModal();render()}
  else if(a==='open-note')noteModal(id);
  else if(a==='save-note')saveNote();
  else if(a==='delete-note'&&confirm('Delete this note?')){state.notes=state.notes.filter(x=>x.id!==id);save();closeModal();render()}
  else if(a==='export-notes')download(`ourspace-notes-${today()}.json`,JSON.stringify({notes:state.notes},null,2));
  else if(a==='insert-checklist'){document.execCommand('insertHTML',false,'<ul><li>☐ Checklist item</li></ul>');document.getElementById('noteEditor').focus()}
  else if(el.dataset.editor){document.execCommand(el.dataset.editor,false,el.dataset.value||null);document.getElementById('noteEditor').focus()}
  else if(a==='edit-list')listModal(id);
  else if(a==='save-list')saveList();
  else if(a==='delete-list'&&confirm('Delete this list?')){state.lists=state.lists.filter(x=>x.id!==id);save();closeModal();render()}
  else if(a==='add-list-item')addListItem(id);
  else if(a==='delete-list-item'){const l=state.lists.find(x=>x.id===el.dataset.list);l.items=l.items.filter(i=>i.id!==id);save(false);render()}
  else if(a==='add-member')memberModal();
  else if(a==='edit-member')memberModal(id);
  else if(a==='save-member')saveMember();
  else if(a==='delete-member'&&id!==ACTIVE_HOUSEHOLD_ID&&confirm('Delete this household member?')){state.household.members=state.household.members.filter(x=>x.id!==id);if(state.currentMemberId===id)state.currentMemberId=state.household.members[0].id;state.tasks.forEach(t=>{if(t.assignee===id)t.assignee='shared'});save();closeModal();render()}
  else if(a==='save-household-name'){state.household.name=document.getElementById('householdName').value.trim()||'OurSpace Household';save();toast('Household name saved.','success')}
  else if(a==='settings-tab'){state.ui.settingsTab=el.dataset.value;save(false);render()}
  else if(a==='save-appearance'){state.settings.theme=document.getElementById('themeSetting').value;state.settings.textScale=Number(document.getElementById('textScaleSetting').value);state.settings.startWeek=Number(document.getElementById('weekStartSetting').value);save();render();toast('Appearance updated.','success')}
  else if(a==='open-retro-appearance'){if(window.OurSpaceRetro?.open)window.OurSpaceRetro.open();else toast('Profile designer is still loading.','error')}
  else if(a==='save-reminders'){state.settings.notifications=document.getElementById('notificationSetting').checked;state.settings.sound=document.getElementById('soundSetting').checked;if(state.settings.notifications&&'Notification'in window&&Notification.permission==='default')Notification.requestPermission().then(()=>{});save();toast('Reminder settings saved.','success')}
  else if(a==='import-open')importModal();
  else if(a==='run-import')runImport();
  else if(a==='export-all')download(`ourspace-household-backup-${today()}.json`,JSON.stringify({...state,exportedAt:nowIso()},null,2));
  else if(a==='export-tasks')download(`ourspace-household-tasks-${today()}.json`,JSON.stringify({tasks:state.tasks.filter(t=>t.type==='task'),care:state.tasks.filter(t=>t.type==='care'),dbt_adhd:state.tasks.filter(t=>t.type==='dbt_adhd')},null,2));
  else if(a==='reset-data'&&confirm('Reset all local organizer data? This cannot be undone unless you exported a backup.')){localStorage.removeItem(STORAGE_KEY);state=defaultState();save();render();toast('Local data reset.')}
  else if(a==='sync-now')syncNow(false);
  else if(a==='test-backend')syncNow(true);
  else if(a==='add-reward')rewardModal();
  else if(a==='edit-reward')rewardModal(id);
  else if(a==='save-reward')saveReward();
  else if(a==='delete-reward'&&confirm('Delete this reward idea?')){state.rewards=state.rewards.filter(x=>x.id!==id);save();closeModal();render()}
  else if(a==='redeem'){const r=state.rewards.find(x=>x.id===id);if(!r||currentWallet()<r.costCopper)return toast('Not enough currency.','error');changeWallet(state.currentMemberId,-r.costCopper,`Redeemed: ${r.title}`,'reward_redemption',r.id);logActivity(`${member().name} redeemed “${r.title}” for ${formatCurrency(r.costCopper)}.`,'reward');save();render();toast('Reward redeemed!','success')}
}
document.addEventListener('click',handleClick);
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.action==='toggle-list-item'){const l=state.lists.find(x=>x.id===el.dataset.list),i=l?.items.find(x=>x.id===el.dataset.id);if(i){i.checked=el.checked;i.checkedAt=el.checked?nowIso():null;save(false);render()}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&e.target.matches('[data-list-input]')){e.preventDefault();addListItem(e.target.dataset.listInput)}});
document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
document.getElementById('fab').addEventListener('click',()=>document.getElementById('fabMenu').classList.toggle('open'));
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('householdSidebar').classList.toggle('open'));
let searchTimer;document.getElementById('householdGlobalSearch').addEventListener('input',e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{state.ui.search=e.target.value;save(false);render()},180)});
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(state.settings.theme==='system')applySettings()});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){try{state=migrate(JSON.parse(e.newValue));render();toast('Organizer updated from another tab.')}catch{}}});
setInterval(checkReminders,60000);setTimeout(checkReminders,1500);
render();
})();
